import{_ as i,C as t,o as a,c as s,E as r,a2 as d}from"./chunks/framework.BdWD-ld-.js";const h="/joinwell52/assets/empty-lookup-20261126/lookup.en.png",y=JSON.parse('{"title":"The order lookup is empty. Should the AI worker send it again?","description":"An empty order lookup leaves an AI worker with a choice. Twenty-four scripted runs and six live handoffs compare an empty list, a matching receipt, and definitive non-admission evidence.","frontmatter":{"title":"The order lookup is empty. Should the AI worker send it again?","description":"An empty order lookup leaves an AI worker with a choice. Twenty-four scripted runs and six live handoffs compare an empty list, a matching receipt, and definitive non-admission evidence.","cover":"/assets/covers/2026-11-26-empty-lookup.png","date":"2026-11-26","published_date":"2026-11-26","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"en","lifecycle":"Published","publication_authorized":true,"lang":"en-US","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-26-empty-lookup.md","filePath":"en/research/2026-11-26-empty-lookup.md","lastUpdated":1795670468000}'),l={name:"en/research/2026-11-26-empty-lookup.md"};function c(p,e,u,m,g,w){const o=t("ArticleCover"),n=t("ArticleTableScroll");return a(),s("div",null,[r(o,{image:"/assets/covers/2026-11-26-empty-lookup.png",kicker:"Digital employees · Execution and recovery",title:"The order lookup is empty. Should the AI worker send it again?",summary:"An empty order lookup leaves an AI worker with a choice. Twenty-four scripted runs and six live handoffs compare an empty list, a matching receipt, and definitive non-admission evidence.",version:"2026-11-26",languageHref:"/zh/research/2026-11-26-empty-lookup",languageLabel:"简体中文"}),r(n,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-order-lookup-is-empty-should-the-ai-worker-send-it-again" tabindex="-1">The order lookup is empty. Should the AI worker send it again? <a class="header-anchor" href="#the-order-lookup-is-empty-should-the-ai-worker-send-it-again" aria-label="Permalink to &quot;The order lookup is empty. Should the AI worker send it again?&quot;">​</a></h1><p>The rental order was submitted, but the screen kept spinning. The incoming AI worker looked up the order by its business reference and found nothing. The customer is waiting for confirmation. Should the worker send the order again?</p><p>A retry helps if the first request never went out. If the order was committed and the lookup is lagging, the same retry can create a second order. Both cases look identical in the list.</p><p>We put those cases side by side using CodeFlowMu’s task interfaces and a synthetic order ledger. <strong>In all three runs where the order was already committed but temporarily invisible, retrying on an empty lookup created a second order.</strong></p><h2 id="why-distinguish-two-kinds-of-timeout" tabindex="-1">Why distinguish two kinds of timeout? <a class="header-anchor" href="#why-distinguish-two-kinds-of-timeout" aria-label="Permalink to &quot;Why distinguish two kinds of timeout?&quot;">​</a></h2><p>StaffDeck, an open-source platform for AI workers, merged an optional write protection for published procedures. A request known to have failed before it was sent can be retried within budget. When a request may have reached the provider, the workflow keeps the original receipt and hands the uncertainty to an owner or administrator. Orca addressed a different write: a worker’s completion report may have been accepted even if the reply timed out. Orca tries to recover the receipt for the same request and preserves uncertainty when the receipt is unavailable. That leads to our question for business operations: <strong>what evidence should an incoming worker have before it sends again?</strong> <a href="https://github.com/OpenBMB/StaffDeck/pull/326" target="_blank" rel="noreferrer">StaffDeck #326</a> · <a href="https://github.com/stablyai/orca/pull/48943" target="_blank" rel="noreferrer">Orca #48943</a></p><h2 id="the-same-empty-list-can-hide-different-ledgers" tabindex="-1">The same empty list can hide different ledgers <a class="header-anchor" href="#the-same-empty-list-can-hide-different-ledgers" aria-label="Permalink to &quot;The same empty list can hide different ledgers&quot;">​</a></h2><p>We wrote synthetic orders into an independent SQLite ledger. The lookup exposed rows only after their configured visibility time. The experiment counted the actual rows separately. That let us commit an order, return an empty lookup, and make the order visible at the next observation point. The synthetic service had no server-side deduplication, so a second write could produce a second row.</p><p>Both policies got the same assignment, transport observation, and lookup result. One retried on an empty lookup. The other retried only when the records said the original request had not been sent, waiting for the next observation when the outcome remained unknown. We ran three repeats per combination to check consistency across the four fixed conditions and two policies.</p><table tabindex="0"><thead><tr><th>What happened before the lookup</th><th>Retry on empty</th><th>Use send evidence</th></tr></thead><tbody><tr><td>Committed, visible at the next observation</td><td>3/3 retried, two orders per run</td><td>0/3 retried, one order per run</td></tr><tr><td>Confirmed never sent</td><td>3/3 retried, one order per run</td><td>3/3 retried, one order per run</td></tr><tr><td>Committed and visible</td><td>0/3 retried, one order per run</td><td>0/3 retried, one order per run</td></tr><tr><td>First request still unresolved at the end</td><td>3/3 retried, one new order observed per run</td><td>0/3 retried, three assignments stayed active</td></tr></tbody></table><p><img src="'+h+'" alt="Both lookups started empty. At the next observation, one policy had two orders and the other had one."></p><p>The first row shows the counterexample. The order already existed when the lookup returned nothing. The last row shows the cost of waiting: three assignments still needed follow-up. The fixture did not change the fate of those original requests after the observation window, so that last row does not measure eventual duplicates. <a href="/joinwell52/assets/empty-lookup-20261126/results.json">All 24 runs</a></p><h2 id="what-should-the-next-worker-inherit" tabindex="-1">What should the next worker inherit? <a class="header-anchor" href="#what-should-the-next-worker-inherit" aria-label="Permalink to &quot;What should the next worker inherit?&quot;">​</a></h2><p>CodeFlowMu is the local multi-agent system we develop. FCoP uses records that link assignments, issues, and reports. Our test program recorded the transport observation in an issue, reopened the product interface, then recovered that observation for the same assignment and attempt. When an order became visible, the program submitted a report and a QA test identity read back its order IDs and count. Cases that remained uncertain stayed active, without a success report.</p><p>The two policies were scripted. The product interfaces for tasks, issues, and reports ran for real. In a live AI workflow, the role instructions can explain when to reconsider a write. The tool can supply evidence about sending and order visibility. The worker still has to judge whether it can send again and explain that decision to the next shift. A lookup receipt records what the tool returned. Permission to attempt another business write depends on what the provider can establish about the original request.</p><h2 id="what-if-the-sending-record-is-gone-too" tabindex="-1">What if the sending record is gone too? <a class="header-anchor" href="#what-if-the-sending-record-is-gone-too" aria-label="Permalink to &quot;What if the sending record is gone too?&quot;">​</a></h2><p>For the follow-up, a live agent replaced the scripted policy. We retained the original request ID on each assignment but deleted the sending record from the temporary workspace. The first order lookup was empty in every case. In a fresh session, the incoming worker used tools to read the assignment, recover the handoff, and query the synthetic order service. Its job was to finish exactly one order. The tools allowed it to create an order, file an evidence-backed report, or record an unresolved issue.</p><p>The cases diverged when the worker asked the provider about the original request. In the first case no receipt was available, but the independent ledger already held a temporarily invisible order. In the second case the list was just as empty, yet a matching provider receipt confirmed the commitment and identified the original order. In the third case the service gave a definitive answer that the original request had never entered processing, and there was no original order in the ledger. The worker received the same tools and role instructions in every case.</p><p>We ran two fresh sessions per condition, using six separate assignments. We counted actual submissions in the tool trace and orders in the independent ledger, then read back the worker’s reasons through the product interfaces.</p><table tabindex="0"><thead><tr><th>Evidence beyond the empty lookup</th><th>Incoming worker’s decision</th><th>What happened in two runs</th></tr></thead><tbody><tr><td>No receipt for the original request</td><td>File an unresolved issue and explain what remains unknown</td><td>No resends. Both tasks stayed active, with one original order each</td></tr><tr><td>Commitment receipt naming the original order</td><td>Recover the existing order ID and report it</td><td>No resends. Both reports went to review, with one original order each</td></tr><tr><td>Definitive confirmation that the original request was never admitted</td><td>Send once and report the new order using its receipt</td><td>One send per task. Both reports went to review, with one new order each</td></tr></tbody></table><p><strong>All six ledgers ended with one order. Four assignments had enough evidence to go to review.</strong> For the two with no receipt, the experimenter could see the original order in the ledger. The worker could not. It recorded what a successor should check instead of claiming a result it had no way to verify. <a href="/joinwell52/assets/empty-lookup-20261126/live-recovery-results.json">All six tool traces and product records</a></p><h2 id="what-should-a-successor-verify-about-a-receipt" tabindex="-1">What should a successor verify about a receipt? <a class="header-anchor" href="#what-should-a-successor-verify-about-a-receipt" aria-label="Permalink to &quot;What should a successor verify about a receipt?&quot;">​</a></h2><p>The handoff gives us two observable checks: <strong>what evidence the worker obtained, and how many times it actually sent the order.</strong> CodeFlowMu preserved the assignment and attempt. FCoP issue and report records carried the reasons for waiting or reporting an order. The agent chose the action. An isolated fixture supplied the provider evidence and ledger. The four submitted reports reached review, and the experiment ended before final acceptance.</p><p>Every receipt in this test clearly matched the original request and business reference. Next, give an incoming worker a commitment receipt that belongs to a different request. Would it check which request the receipt belongs to before proceeding? That would test whether the worker can use a receipt to establish that this assignment is complete.</p>',24))])}const v=i(l,[["render",c]]);export{y as __pageData,v as default};
